-- # Each function that vsql has beyond the standard is an external function of
-- # the VSQL schema (6.40, Description, 1, 2, 5, 7 and 12.a). A built-in
-- # function is deterministic, contains no SQL, and returns NULL when an
-- # argument is NULL (Description, 8, 9 and 10). The data type of the result is
-- # described like the data type of a column, and is identified by 0.
SELECT * FROM information_schema.routines WHERE routine_name = 'CBRT';
-- SPECIFIC_CATALOG: :memory: SPECIFIC_SCHEMA: VSQL SPECIFIC_NAME: CBRT_1 ROUTINE_CATALOG: :memory: ROUTINE_SCHEMA: VSQL ROUTINE_NAME: CBRT ROUTINE_TYPE: FUNCTION MODULE_CATALOG: NULL MODULE_SCHEMA: NULL MODULE_NAME: NULL UDT_CATALOG: NULL UDT_SCHEMA: NULL UDT_NAME: NULL DATA_TYPE: DOUBLE PRECISION CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_OCTET_LENGTH: NULL CHARACTER_SET_CATALOG: NULL CHARACTER_SET_SCHEMA: NULL CHARACTER_SET_NAME: NULL COLLATION_CATALOG: NULL COLLATION_SCHEMA: NULL COLLATION_NAME: NULL NUMERIC_PRECISION: 53 NUMERIC_PRECISION_RADIX: 2 NUMERIC_SCALE: NULL DATETIME_PRECISION: NULL INTERVAL_TYPE: NULL INTERVAL_PRECISION: NULL TYPE_UDT_CATALOG: NULL TYPE_UDT_SCHEMA: NULL TYPE_UDT_NAME: NULL SCOPE_CATALOG: NULL SCOPE_SCHEMA: NULL SCOPE_NAME: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 0 ROUTINE_BODY: EXTERNAL ROUTINE_DEFINITION: NULL EXTERNAL_NAME: CBRT EXTERNAL_LANGUAGE: C PARAMETER_STYLE: GENERAL IS_DETERMINISTIC: YES SQL_DATA_ACCESS: NO SQL IS_NULL_CALL: YES SQL_PATH: NULL SCHEMA_LEVEL_ROUTINE: YES MAX_DYNAMIC_RESULT_SETS: 0 IS_USER_DEFINED_CAST: NO IS_IMPLICITLY_INVOCABLE: NULL SECURITY_TYPE: IMPLEMENTATION DEFINED TO_SQL_SPECIFIC_CATALOG: NULL TO_SQL_SPECIFIC_SCHEMA: NULL TO_SQL_SPECIFIC_NAME: NULL AS_LOCATOR: NO CREATED: NULL LAST_ALTERED: NULL NEW_SAVEPOINT_LEVEL: NULL IS_UDT_DEPENDENT: NO RESULT_CAST_FROM_DATA_TYPE: NULL RESULT_CAST_AS_LOCATOR: NULL RESULT_CAST_CHAR_MAX_LENGTH: NULL RESULT_CAST_CHAR_OCTET_LENGTH: NULL RESULT_CAST_CHAR_SET_CATALOG: NULL RESULT_CAST_CHAR_SET_SCHEMA: NULL RESULT_CAST_CHARACTER_SET_NAME: NULL RESULT_CAST_COLLATION_CATALOG: NULL RESULT_CAST_COLLATION_SCHEMA: NULL RESULT_CAST_COLLATION_NAME: NULL RESULT_CAST_NUMERIC_PRECISION: NULL RESULT_CAST_NUMERIC_RADIX: NULL RESULT_CAST_NUMERIC_SCALE: NULL RESULT_CAST_DATETIME_PRECISION: NULL RESULT_CAST_INTERVAL_TYPE: NULL RESULT_CAST_INTERVAL_PRECISION: NULL RESULT_CAST_TYPE_UDT_CATALOG: NULL RESULT_CAST_TYPE_UDT_SCHEMA: NULL RESULT_CAST_TYPE_UDT_NAME: NULL RESULT_CAST_SCOPE_CATALOG: NULL RESULT_CAST_SCOPE_SCHEMA: NULL RESULT_CAST_SCOPE_NAME: NULL RESULT_CAST_MAX_CARDINALITY: NULL RESULT_CAST_DTD_IDENTIFIER: NULL

-- # Each overload is its own routine, with a specific name that's numbered in
-- # the order they're registered (6.40, Description, 1). They're ordered by
-- # name, then by that number.
SELECT specific_name, data_type FROM information_schema.routines WHERE routine_name IN ('MAKE_DATE', 'SIGN', 'PI');
-- SPECIFIC_NAME: MAKE_DATE_1 DATA_TYPE: DATE
-- SPECIFIC_NAME: PI_1 DATA_TYPE: DOUBLE PRECISION
-- SPECIFIC_NAME: SIGN_1 DATA_TYPE: DOUBLE PRECISION
-- SPECIFIC_NAME: SIGN_2 DATA_TYPE: NUMERIC
-- SPECIFIC_NAME: SIGN_3 DATA_TYPE: SMALLINT
-- SPECIFIC_NAME: SIGN_4 DATA_TYPE: INTEGER
-- SPECIFIC_NAME: SIGN_5 DATA_TYPE: BIGINT

-- # A function that can return a different result for the same arguments isn't
-- # deterministic (6.40, Description, 9). A character string result can have
-- # any length.
SELECT routine_name, is_deterministic FROM information_schema.routines WHERE routine_name IN ('NOW', 'RANDOM');
SELECT data_type, character_maximum_length, character_octet_length, character_set_name FROM information_schema.routines WHERE routine_name = 'SPLIT_PART';
-- ROUTINE_NAME: NOW IS_DETERMINISTIC: NO
-- ROUTINE_NAME: RANDOM IS_DETERMINISTIC: NO
-- DATA_TYPE: CHARACTER VARYING CHARACTER_MAXIMUM_LENGTH: 10485760 CHARACTER_OCTET_LENGTH: 41943040 CHARACTER_SET_NAME: UTF8

-- # A standard function isn't a routine, it's part of the grammar. Neither is an
-- # aggregate function, even one that's a vsql extension, such as PRODUCT.
SELECT COUNT(*) FROM information_schema.routines WHERE routine_name IN ('ABS', 'UPPER', 'COUNT', 'PRODUCT');
-- COL1: 0

-- # The PostgreSQL functions are routines when they're registered for
-- # PostgreSQL clients. They're called when an argument is NULL, so
-- # IS_NULL_CALL is NO (6.40, Description, 10).
/* postgresql */
SELECT specific_name, is_deterministic, sql_data_access, is_null_call FROM information_schema.routines WHERE routine_name = 'VERSION';
-- SPECIFIC_NAME: VERSION_1 IS_DETERMINISTIC: NO SQL_DATA_ACCESS: NO SQL IS_NULL_CALL: NO

-- # The short name view ROUTINES_S has the same rows (5.77).
SELECT specific_name, char_max_length, sch_level_routine, max_dyn_reslt_sets, is_user_defnd_cast, rc_from_data_type FROM information_schema.routines_s WHERE routine_name = 'SPLIT_PART';
-- SPECIFIC_NAME: SPLIT_PART_1 CHAR_MAX_LENGTH: 10485760 SCH_LEVEL_ROUTINE: YES MAX_DYN_RESLT_SETS: 0 IS_USER_DEFND_CAST: NO RC_FROM_DATA_TYPE: NULL

-- # The views are in the INFORMATION_SCHEMA, and describe themselves.
SELECT table_name, table_type FROM information_schema.tables WHERE table_name IN ('ROUTINES', 'ROUTINES_S', 'PARAMETERS', 'PARAMETERS_S');
-- TABLE_NAME: PARAMETERS TABLE_TYPE: VIEW
-- TABLE_NAME: PARAMETERS_S TABLE_TYPE: VIEW
-- TABLE_NAME: ROUTINES TABLE_TYPE: VIEW
-- TABLE_NAME: ROUTINES_S TABLE_TYPE: VIEW
